package com.ptms.service;import com.ptms.domain.PersonType;import com.ptms.dto.SettingsDto;import org.junit.jupiter.api.Test;import java.time.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;class ParkingDurationServiceTest{private ParkingDurationService service(){SettingsService s=mock(SettingsService.class);when(s.get()).thenReturn(new SettingsDto("06:00","12:00","06:00","12:30",0,"1,2,4,6,8,12",5,5,5,5,5,5,"DAY",7,"","",1,"NONE","PHOTO","NORMAL","EMPLOYEE","HOURS","SCAN",1,true,true,true,true,true,true,true,true));return new ParkingDurationService(s);}@Test void weekdayPass(){int h=service().requiredTicketHours(PersonType.EMPLOYEE,true,LocalDate.of(2026,9,14),LocalTime.of(8,0),LocalTime.of(17,0),null);assertThat(h).isEqualTo(5);}@Test void weekendPass(){int h=service().requiredTicketHours(PersonType.EMPLOYEE,true,LocalDate.of(2026,9,19),LocalTime.of(8,0),LocalTime.of(14,0),null);assertThat(h).isEqualTo(2);}@Test void noPassWithoutExtraHoursStillCalculates(){int h=service().requiredTicketHours(PersonType.EMPLOYEE,false,LocalDate.of(2026,9,14),LocalTime.of(8,0),LocalTime.of(17,0),null);assertThat(h).isEqualTo(9);}}
